"""Publication cleanup must release generated bytes while preserving all inputs."""
import asyncio
import importlib.util
import json
import os
import secrets
from contextlib import asynccontextmanager
from pathlib import Path
from threading import Event

import pytest

from misong import cleanup, pack, workflows
from misong.jobs import fingerprint, save_json
from misong.publish import Paused, PublishOptions, import_share, prepare, publish
from misong.sharing import ShareInfo
from test_packaging_redesign import video  # real ffmpeg-generated fixture


def load(path):
    return json.loads(path.read_text(encoding='utf-8'))


def make_job(tmp_path, **options):
    source = tmp_path / 'source'
    source.mkdir()
    (source / '随机源.bin').write_bytes(os.urandom(25000))
    options = {'size': '8192B', 'checksum': True, 'schemes': ('base64',),
               'cleanup_after_upload': True, **options}
    path = prepare(PublishOptions([source], tmp_path / 'out',
                   [pack.LayerSpec('zip', secrets.token_urlsafe(20))], **options), lambda _: None)
    return path, source


class Runtime:
    def __init__(self, path, *, fail_disk=None, after_share=None):
        self.path, self.fail_disk, self.after_share = path, fail_disk, after_share
        self.events = []

    @asynccontextmanager
    async def open(self, disk):
        runtime = self

        class Driver:
            async def upload(self, page, files, folder):
                # Body bytes must still exist at the last disk / relay upload.
                plan = load(runtime.path)
                assert all(Path(item['path']).is_file() for stage in plan['stages'] for item in stage['files'])
                runtime.events.append(('upload', disk))
                if disk == runtime.fail_disk:
                    raise RuntimeError('test upload failure')
                return [folder]

            async def share(self, page, targets):
                runtime.events.append(('share', disk))
                if runtime.after_share:
                    runtime.after_share(disk)
                return ShareInfo(disk, 'https://pan.quark.cn/s/test-cleanup', 'a123', '1天')
        yield Driver(), None


def run(path, runtime=None, **kwargs):
    return asyncio.run(publish(path, runtime=runtime or Runtime(path), notify=lambda _: None, **kwargs))


@pytest.mark.parametrize('legacy', [False, True])
def test_default_and_legacy_tasks_retain_outputs(tmp_path, legacy):
    path, source = make_job(tmp_path, cleanup_after_upload=False)
    if legacy:
        plan = load(path)
        plan.pop('local_cleanup')
        save_json(path, plan)
    run(path)
    assert (source / '随机源.bin').is_file()
    assert all(Path(rec['path']).is_file() for rec in load(path)['stages'][0]['files'])


@pytest.mark.parametrize('form', ['direct', 'simple', 'complex'])
def test_all_disks_and_relay_finish_before_cleanup_and_replay(tmp_path, form):
    path, source = make_job(tmp_path, form=form, body_disks=('quark', 'xunlei'))
    original = (source / '随机源.bin').read_bytes()
    unrelated = path.parent / 'body/unrelated.zip'
    unrelated.write_bytes(b'not made by publication')
    result = run(path, hop_password=secrets.token_urlsafe(20))
    plan = result['plan']
    assert plan['state'] == 'complete' and cleanup.summary(plan)['state'] == 'complete'
    assert all(not Path(rec['path']).exists() for rec in plan['local_cleanup']['files'])
    assert (source / '随机源.bin').read_bytes() == original
    assert unrelated.read_bytes() == b'not made by publication'
    assert (path.parent / 'body/RESTORE.txt').is_file()
    assert list((path.parent / 'body').glob('*.misong.json'))
    assert list((path.parent / 'body').glob('*.misongsplit.json'))
    assert (path.parent / 'misong-task.json').is_file()
    assert (path.parent / 'copy/share-plain.txt').is_file()
    again = Runtime(path)
    run(path, again)
    assert again.events == []
    if form != 'direct':
        import_share(path, 'body', 'https://pan.quark.cn/s/new-cleanup-link')
        # Already-cleaned body outputs need not be recreated to replace a relay link.
        # Inspect only new relay generation; old body entries intentionally stay absent.
        from test_publish import FakeRuntime
        relay = FakeRuntime()
        run(path, relay, hop_password=secrets.token_urlsafe(20))
        assert all(event[1] == 'feimao' for event in relay.events if event[0] == 'open')
        assert cleanup.summary(load(path))['state'] == 'complete'


def test_prepare_only_and_second_disk_failure_preserve_every_output(tmp_path):
    path, source = make_job(tmp_path, body_disks=('quark', 'xunlei'))
    records = load(path)['local_cleanup']['files']
    assert all(Path(rec['path']).exists() for rec in records)  # prepare only
    with pytest.raises(RuntimeError, match='upload failure'):
        run(path, Runtime(path, fail_disk='xunlei'))
    assert load(path)['state'] == 'blocked'
    assert all(Path(rec['path']).exists() for rec in records)
    run(path)
    assert cleanup.summary(load(path))['state'] == 'complete'
    assert (source / '随机源.bin').is_file()


def test_pause_after_share_preserves_outputs_until_resume(tmp_path):
    path, _ = make_job(tmp_path)
    cancel = Event()
    with pytest.raises(Paused):
        run(path, Runtime(path, after_share=lambda _: cancel.set()), cancel=cancel)
    assert all(Path(rec['path']).exists() for rec in load(path)['local_cleanup']['files'])
    run(path)
    assert cleanup.summary(load(path))['state'] == 'complete'


@pytest.mark.parametrize('stage', ['share', 'copy'])
def test_share_or_copy_failure_never_cleans_outputs(tmp_path, monkeypatch, stage):
    import importlib
    path, _ = make_job(tmp_path)

    def fail(*args, **kwargs):
        raise RuntimeError('test completion failure')

    with monkeypatch.context() as patch:
        if stage == 'copy':
            patch.setattr(importlib.import_module('misong.publish'), 'write_copy', fail)
        with pytest.raises(RuntimeError, match='completion failure'):
            run(path, Runtime(path, after_share=fail if stage == 'share' else None))
    assert all(Path(rec['path']).is_file() for rec in load(path)['local_cleanup']['files'])
    run(path)
    assert cleanup.summary(load(path))['state'] == 'complete'


def test_cover_output_removed_but_original_video_and_source_remain(tmp_path, video):
    src = tmp_path / 'source.bin'
    src.write_bytes(os.urandom(4096))
    before = [fingerprint(p) for p in (src, video)]
    path = prepare(PublishOptions([src], tmp_path / 'out',
                   [pack.LayerSpec('zip', secrets.token_urlsafe(20)),
                    pack.LayerSpec(type='cover', video=str(video))], size='',
                   schemes=('base64',), cleanup_after_upload=True), lambda _: None)
    run(path)
    assert all(fingerprint(p) == rec for p, rec in zip((src, video), before))
    assert not list((path.parent / 'body').glob('*.mp4'))
    assert cleanup.summary(load(path))['state'] == 'complete'


def test_manual_link_does_not_prove_uploaded_bytes(tmp_path):
    path, _ = make_job(tmp_path)
    import_share(path, 'body', 'https://pan.quark.cn/s/manual-cleanup-link')
    run(path)
    plan = load(path)
    assert plan['state'] == 'complete' and cleanup.summary(plan)['state'] == 'retained'
    assert all(Path(rec['path']).exists() for rec in plan['local_cleanup']['files'])


def test_changed_artifact_is_retained_without_losing_success(tmp_path):
    path, _ = make_job(tmp_path)
    changed = Path(load(path)['local_cleanup']['files'][0]['path'])
    run(path, Runtime(path, after_share=lambda _: changed.write_bytes(b'owner replacement')))
    plan = load(path)
    assert plan['state'] == 'complete' and cleanup.summary(plan)['state'] == 'partial'
    assert changed.read_bytes() == b'owner replacement'
    assert cleanup.summary(plan)['retained'] == 1


def test_locked_artifact_can_retry_without_upload(tmp_path, monkeypatch):
    path, _ = make_job(tmp_path)
    locked = Path(load(path)['local_cleanup']['files'][0]['path'])
    unlink = Path.unlink

    def fail(candidate, *args, **kwargs):
        if candidate == locked:
            raise PermissionError('test file lock')
        return unlink(candidate, *args, **kwargs)

    with monkeypatch.context() as patch:
        patch.setattr(Path, 'unlink', fail)
        run(path)
    assert load(path)['state'] == 'complete' and locked.exists()
    assert cleanup.summary(load(path))['state'] == 'partial'
    retry = Runtime(path)
    run(path, retry)
    assert retry.events == [] and not locked.exists()


def test_interrupted_cleanup_can_resume_missing_owned_file(tmp_path, monkeypatch):
    path, _ = make_job(tmp_path)
    unlink = Path.unlink
    victim = Path(load(path)['local_cleanup']['files'][0]['path'])

    def interrupt(candidate, *args, **kwargs):
        result = unlink(candidate, *args, **kwargs)
        if candidate == victim:
            raise KeyboardInterrupt()
        return result

    with monkeypatch.context() as patch:
        patch.setattr(Path, 'unlink', interrupt)
        with pytest.raises(KeyboardInterrupt):
            run(path)
    assert load(path)['state'] == 'complete'
    retry = Runtime(path)
    run(path, retry)
    assert retry.events == [] and cleanup.summary(load(path))['state'] == 'complete'


@pytest.mark.parametrize('kind', ['external', 'source_hardlink', 'source_directory', 'linked_body', 'moved_root'])
def test_cleanup_rejects_paths_not_owned_by_current_task(tmp_path, kind, monkeypatch):
    path, source = make_job(tmp_path, cleanup_after_upload=False)
    run(path)  # produce fully confirmed checkpoint without removing files
    plan = load(path)
    plan['local_cleanup']['enabled'] = True
    original = source / '随机源.bin'
    protected = original
    if kind == 'external':
        plan['local_cleanup']['files'].append({**fingerprint(original), 'state': 'pending'})
    elif kind == 'source_hardlink':
        protected = path.parent / 'body/source-alias.zip'
        protected.hardlink_to(original)
        plan['local_cleanup']['files'].append({**fingerprint(protected), 'state': 'pending'})
    elif kind == 'source_directory':
        plan['local_cleanup']['sources'].append(str(path.parent / 'body'))
        protected = Path(plan['local_cleanup']['files'][0]['path'])
    elif kind == 'linked_body':
        is_symlink = Path.is_symlink
        monkeypatch.setattr(Path, 'is_symlink', lambda p: p == path.parent / 'body' or is_symlink(p))
        protected = Path(plan['local_cleanup']['files'][0]['path'])
    else:
        plan['local_cleanup']['root'] = str(tmp_path / 'different-task')
        protected = Path(plan['local_cleanup']['files'][0]['path'])
    cleanup.remove_generated(path, plan, lambda: save_json(path, plan), lambda _: None)
    assert protected.exists() and original.is_file()
    assert cleanup.summary(plan)['state'] in ('partial', 'retained')


def test_standalone_upload_never_deletes_selected_archive(tmp_path):
    src = tmp_path / 'already-processed.zip'
    src.write_bytes(os.urandom(1000))
    before = fingerprint(src)
    path = workflows.prepare_upload([src], tmp_path / 'upload', ['quark'], schemes=('base64',), notify=lambda _: None)
    from test_publish import FakeRuntime
    run(path, FakeRuntime())
    assert fingerprint(src) == before and 'local_cleanup' not in load(path)


def test_cli_cleanup_is_explicit_and_cannot_override_resume(tmp_path):
    from misong.cli import main
    src = tmp_path / 'generated.bin'
    src.write_bytes(os.urandom(1024))
    out = tmp_path / 'cli-out'
    assert main(['publish', str(src), '-o', str(out), '-L', 'zip', '--prepare',
                 '--cleanup-after-upload', '--schemes', 'base64']) == 0
    path = out / 'relay-plan.json'
    assert load(path)['local_cleanup']['enabled'] is True
    assert all(Path(rec['path']).exists() for rec in load(path)['local_cleanup']['files'])
    assert main(['publish', '--plan', str(path), '--prepare', '--cleanup-after-upload']) != 0


def test_desktop_cleanup_default_off_prepare_retains_and_summary_survives(tmp_path):
    from misong.desktop.api import Api
    from test_desktop_api import FakeRuntime, ok, wait_job
    src = tmp_path / 'generated.bin'
    src.write_bytes(os.urandom(4096))
    api = Api(tmp_path / 'runs', tmp_path / 'state', runtime_factory=FakeRuntime)
    cfg = {'inputs': [str(src)], 'layers': [{'fmt': 'zip'}], 'layers_version': 2,
           'body_disks': ['quark'], 'schemes': ['base64'], 'cleanup_after_upload': True, 'upload': False}
    ok(api.start_pipeline(cfg))
    event = wait_job(api)
    assert event['state'] == 'done'
    path = Path(event['result']['plan'])
    assert all(Path(item['path']).is_file() for item in load(path)['local_cleanup']['files'])
    ok(api.resume_task(str(path)))
    event = wait_job(api)
    assert event['state'] == 'done'
    task = ok(api.task_detail(str(path)))
    assert task['cleanup']['state'] == 'complete' and task['settings']['cleanup_after_upload'] is True
    assert src.is_file() and len(ok(api.list_tasks())) == 1
    # The destructive choice is per task, never remembered as a global default.
    ok(api.save_settings({'cleanup_after_upload': True}))
    assert 'cleanup_after_upload' not in ok(api.bootstrap())['settings']


@pytest.mark.parametrize('cleanup_state', ['complete', 'partial'])
def test_ui_cleanup_choice_is_pipeline_only_and_resets_on_reuse(tmp_path, cleanup_state):
    pw = pytest.importorskip('playwright.sync_api')
    from misong.desktop.api import Api
    root = Path(__file__).resolve().parents[1]
    spec = importlib.util.spec_from_file_location('preview_cleanup', root / 'scripts/ui_preview.py')
    preview = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(preview)
    fake = preview.Fake(Api(tmp_path / 'runs', tmp_path / 'state'))

    def bridge(method, args):
        result = fake(method, args)
        if method == 'task_detail':
            result['data']['cleanup'] = {'enabled': True, 'state': cleanup_state, 'deleted': 5, 'retained': 1}
        return result

    with pw.sync_playwright() as p:
        browser = p.chromium.launch(headless=True)
        page = browser.new_page()
        page.expose_function('__py', bridge)
        page.add_init_script(preview.MOCK_JS)
        page.goto(preview.WEB.as_uri())
        page.wait_for_selector('.page.active [data-act="pick-files"]')
        # Show the real wizard's packing options without starting any upload.
        page.locator('.page.active [data-act="pick-files"]').click()
        page.get_by_role('button', name='确认，下一步：加密打包', exact=True).click()
        checkbox = page.get_by_label('上传完成后删除本地加工产物', exact=True)
        assert not checkbox.is_checked()
        checkbox.check()
        assert page.evaluate('window.__MISONG_APP__.S.pipeline.cleanup_after_upload') is True
        assert '分享完成后删除' in page.locator('.page.active [data-mount="run"]').inner_text()
        page.get_by_role('button', name='加密打包', exact=True).click()
        assert page.locator('.page.active [data-model="cleanup_after_upload"]').count() == 0
        page.get_by_role('button', name='上传分享', exact=True).click()
        assert page.locator('.page.active [data-model="cleanup_after_upload"]').count() == 0
        page.get_by_role('button', name='任务中心', exact=False).first.click()
        page.locator('.task[data-task]').first.click()
        page.locator('#taskDetail .callout').filter(has_text='源文件').wait_for()
        assert ('已删除 5 个' if cleanup_state == 'complete' else '部分加工产物未清理') in page.locator('#taskDetail').inner_text()
        page.locator('[data-reuse]').click()
        assert page.evaluate('window.__MISONG_APP__.S.pipeline.cleanup_after_upload') is False
        browser.close()
